    Queue ← ⟨all literals in g⟩; Examined ← Ø
    while Queue ≠ ⟨⟩ do
        φ ← pop(Queue)
        if φ ∈ Examined and s₀ ≠ φ then
            // Step 1: look for an “action landmark”
            R ← {actions whose effects include a literal in φ}
            generate RPG from s₀ using A \ R, stopping when ŝₖ = ŝₖ₋₁
            // ŝₖ now includes every atom that’s achievable without R
            N ← {all actions in R that are r-applicable in ŝₖ}
            if N = Ø then return failure
            // Step 2: get new landmarks from actions’ preconditions
            Φ ← {p₁ ∨ p₂ ∨ ... ∨ pₘ | m ≤ 4,
                each pᵢ is a precondition of at least one a ∈ N, and
                each a ∈ N has at least one pᵢ as a precondition}
            append to Queue every φ ∈ Φ that isn’t subsumed by another
